/* Hide edit view by default */
.edit-view {
    display: none;
}

/* When edit mode is ON */
.edit-mode #middle_section_default .edit-view {
    display: block;
}

.edit-mode #middle_section_default .default-view {
    display: none;
}

/* ===== Stylish Processing UI ===== */
.processing-box {
    text-align: center;
    padding: 150px 20px;
    border-radius: 12px;
    background-image: linear-gradient(to top, #dee7de 0%, #fff4dc 1%, #fff 31%, #ffe5b02e 75%, #ffe7b7 100%);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.1);
    animation: fadeIn 0.6s ease;
}

.processing-box h2 {
    font-size: 43px;
    font-weight: 700;
    color: #2a2d38;
    margin-bottom: 10px;
}

.processing-box p {
    font-size: 30px;
    color: #6c757d;
}

/* Optional animation */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}
