    font-size: 32px;
    font-weight: 700;
    margin-bottom: 10px;
}

.home-47-title h2 span {
    color: #000;
}

.home-47-title p {
    max-width: 700px;
    margin: 10px auto 40px;
    color: #777;
}

.home-47-step {
    margin-bottom: 30px;
}

.home-47-step .home-47-img-circle {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0 auto 20px;
    border: 4px solid #ffd57e;
    position: relative;
}

.home-47-step .home-47-img-circle img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.home-47-step .home-47-number {
    position: absolute;
    bottom: 7px;
    left: 50%;
    transform: translateX(-50%);
    background-color: #58b957;
    color: #fff;
    border-radius: 50%;
    width: 30px;
    height: 30px;
    line-height: 30px;
    font-size: 14px;
    font-weight: bold;
    z-index: 1;
}

.home-47-step h4 {
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 10px;
}

.home-47-step p {
    font-size: 13px;
    color: #777;
}

.home-47-arrow {
    font-size: 24px;
    color: #ccc;
    margin: 10px auto;
}

@media (max-width: 767px) {
    .home-47-arrow {
        display: none;
    }
}

@keyframes fadeInUp {
    0% {
        opacity: 0;
        transform: translateY(30px);
    }

    100% {
        opacity: 1;
        transform: translateY(0);
    }
}

.home-47-steps-wrapper {
    position: relative;
}

.home-47-step {
    position: relative;
    animation: fadeInUp 0.7s ease both;
}

.home-47-step.animated.delay-1 {
    animation-delay: 0.2s;
}

.home-47-step.animated.delay-2 {
    animation-delay: 0.4s;
}

.home-47-step.animated.delay-3 {
    animation-delay: 0.6s;
}

.home-47-img-circle {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.home-47-img-circle:hover {
    transform: scale(1.25);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
}

/* Optional Arrows (between steps) */
.home-47-steps-wrapper::before {
    content: '';
    position: absolute;
    top: 60px;
    left: 16.6%;
    right: 16.6%;
    height: 1px;
    border-top: 2px dashed #ccc;
    z-index: 0;
}

@media (max-width: 767px) {
    .home-47-steps-wrapper::before {
        display: none;
    }
}



