    overflow: hidden;
}

.blog-13 .card img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform .5s ease;
}

.blog-13 .card:hover img {
    transform: scale(1.08);
}

