    text-shadow: 0 10px 30px rgba(0, 0, 0, .35);
}

/* Text Animation */

.home-56 .home-56-content p span {
    display: inline;
    color: #fff;
    opacity: .18;
    transition:
        opacity .35s ease,
        color .35s ease;
    animation: home56-highlight both ease-in-out;
    animation-timeline: view();
}

@keyframes home56-highlight {

    50% {
        opacity: 1;
        color: var(--primary, #fff);
    }

}

/* Individual Text Timing */

.home-56 .home-56-content p span:nth-of-type(1) {
    animation-range: cover 10% cover 45%;
}

.home-56 .home-56-content p span:nth-of-type(2) {
    animation-range: cover 30% cover 60%;
}

.home-56 .home-56-content p span:nth-of-type(3) {
    animation-range: cover 45% cover 85%;
}

.home-56 .home-56-content p span:nth-of-type(4) {
    animation-range: cover 75% cover 120%;
}

/* Background Video */

.home-56 .home-56-video {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100vh;
    object-fit: cover;
    z-index: 0;
    opacity: .28;
    filter: saturate(.2) brightness(.45);
    pointer-events: none;
}

/* Video Scroll Fade */

@supports (animation-timeline: view()) {

    .home-56 .home-56-video {
        opacity: 0;
        animation:
            home56-fade-in both linear,
            home56-fade-out both linear;
        animation-timeline: --home56-section;
        animation-range:
            entry 10% entry 25%,
            exit 10% exit 25%;
    }

    @keyframes home56-fade-in {

        from {
            opacity: 0;
        }

        to {
            opacity: .35;
        }

    }

    @keyframes home56-fade-out {

        from {
            opacity: .35;
        }

        to {
            opacity: 0;
        }

    }

}

/* Tablet */

@media (max-width: 991px) {

