}

.home-68 .home-68-visual-wrap {
    position: relative;
    perspective: 1000px;
}

.home-68 .home-68-card {
    position: relative;
    width: 100%;
    max-width: 440px;
    margin: 10px auto;
    transform-style: preserve-3d;
    will-change: transform;
}

.home-68 .home-68-portrait {
    position: relative;
    width: 100%;
    padding-top: 115%;
    overflow: hidden;
    background: var(--light, #e8eefc);
    border-radius: 28px;
    box-shadow: 0 25px 60px rgba(0, 0, 0, .25);
}

.home-68 .home-68-portrait img {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform .45s ease;
    clip-path: polygon(10% 15%, 5% 35%, 8% 70%, 18% 88%, 30% 100%, 70% 100%, 84% 86%, 96% 71%, 102% 35%, 92% 18%, 80% 0%, 18% 0%);
}

.home-68 .home-68-card:hover .home-68-portrait img {
    transform: scale(1.05);
}

.home-68 .home-68-skill {
    --size: 58px;
    position: absolute;
    width: var(--size);
    height: var(--size);
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    color: #fff;
    font-size: 26px;
    cursor: pointer;
    transform: translateZ(40px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, .2);
    transition: transform .3s ease;
}

.home-68 .home-68-skill:hover {
    transform: translateZ(40px) scale(1.08);
}

.home-68 .home-68-skill.home-68-s1 {
    top: -16px;
    left: -16px;
    background: var(--text, #111);
}

.home-68 .home-68-skill.home-68-s2 {
    top: 30%;
    right: -22px;
    background: #0ea5e9;
}

.home-68 .home-68-skill.home-68-s3 {
    bottom: -18px;
    left: 35%;
    background: #fff;
    color: var(--text, #111);
    border: 1px solid rgba(17, 17, 17, .08);
}

.home-68 .home-68-skill[data-tip]:hover:after {
    content: attr(data-tip);
    position: absolute;
    left: 50%;
    bottom: calc(100% + 8px);
    transform: translateX(-50%);
    padding: 6px 10px;
    border-radius: 6px;
    background: var(--text, #111);
    color: #fff;
    font-size: 12px;
    white-space: nowrap;
    box-shadow: 0 10px 18px rgba(0, 0, 0, .15);
}

.home-68 .home-68-scroll-dot {
    position: absolute;
    left: 50%;
    bottom: 16px;
    width: 22px;
    height: 36px;
    border: 2px solid #fff;
    border-radius: 16px;
    transform: translateX(-50%);
}

.home-68 .home-68-scroll-dot:after {
    content: "";
    position: absolute;
    left: 50%;
    top: 6px;
    width: 4px;
    height: 6px;
    border-radius: 2px;
    background: #fff;
    transform: translateX(-50%);
    animation: home-68-scroll-dot-68 1.4s infinite;
}

@keyframes home-68-scroll-dot-68 {
    0% {
        opacity: 1;
        transform: translate(-50%, 0);
    }

    100% {
        opacity: 0;
        transform: translate(-50%, 12px);
    }
}

