    transform: scale(1.06);
}

.about-42 .about-42-card:before {
    content: "";
    position: absolute;
    inset: -2px;
    z-index: 2;
    border: 4px solid transparent;
    border-radius: 18px;
    pointer-events: none;
}

.about-42 .about-42-card.red:hover:before,
.about-42 .about-42-card.green:hover:before,
.about-42 .about-42-card.yellow:hover:before {
