    color: #fff;
    text-align: center;
}

.home-75 * {
    font-family: "Poppins", sans-serif;
}

.home-75-heading h2 {
    margin: 0 0 40px;
    color: #fff;
    font-size: 42px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: 1px;
}

.home-75-gallery {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 20px;
    transform-style: preserve-3d;
    transition: transform .5s ease;
}

.home-75-card {
    position: relative;
    width: 200px;
    height: 280px;
    overflow: hidden;
    cursor: pointer;
    border-radius: 18px;
    background: #222;
    box-shadow: 0 18px 45px rgba(0, 0, 0, .55);
    transform-origin: center center;
    transition: transform .45s ease, opacity .45s ease, box-shadow .45s ease;
}

.home-75-card img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    transition: transform .45s ease, filter .45s ease;
}

.home-75-card:hover {
    transform: scale(1.35) translateY(-20px);
    z-index: 10;
    box-shadow: 0 28px 60px rgba(0, 0, 0, .7);
}

.home-75-card:hover img {
    transform: scale(1.08);
    filter: brightness(1.1);
}

.home-75-gallery:hover .home-75-card:not(:hover) {
    opacity: .7;
    transform: scale(.9);
}

.home-75-card:nth-child(1) {
    transform: rotateY(-50deg) translateZ(-150px);
}

.home-75-card:nth-child(2) {
    transform: rotateY(-35deg) translateZ(-80px);
}

.home-75-card:nth-child(3) {
    transform: rotateY(-20deg) translateZ(0);
}

.home-75-card:nth-child(4) {
    transform: rotateY(0deg) translateZ(80px);
}

.home-75-card:nth-child(5) {
    transform: rotateY(20deg) translateZ(0);
}

.home-75-card:nth-child(6) {
    transform: rotateY(35deg) translateZ(-80px);
}

.home-75-card:nth-child(7) {
    transform: rotateY(50deg) translateZ(-150px);
}

.home-75-caption {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    padding: 10px 12px;
    background: linear-gradient(to top, rgba(0, 0, 0, .8), rgba(0, 0, 0, .35));
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    pointer-events: none;
}

@media(max-width:991px) {

