    background: var(--light, #fff);
    box-shadow: 0 14px 35px rgba(0, 0, 0, .06);
}

.blog-16 .blog-16-card-large {
    display: flex;
    flex-direction: column;
    width: 100%;
    overflow: hidden;
    border-radius: 20px;
    transition: transform .35s ease, box-shadow .35s ease;
}

.blog-16 .blog-16-card-large:hover {
    box-shadow: 0 22px 48px rgba(0, 0, 0, .1);
    transform: translateY(-5px);
}

.blog-16 .blog-16-large-image {
    position: relative;
    width: 100%;
    height: 350px;
    overflow: hidden;
    background: var(--secondary, #222);
}

.blog-16 .blog-16-large-image img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform .55s ease;
}

.blog-16 .blog-16-card-large:hover .blog-16-large-image img {
    transform: scale(1.04);
}

.blog-16 .blog-16-category {
    position: absolute;
    top: 17px;
    left: 17px;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    min-height: 28px;
    padding: 6px 11px;
    border: 1px solid rgba(255, 255, 255, .5);
    border-radius: 50px;
    background: rgba(255, 255, 255, .9);
    color: var(--primary, #0a1a44);
    font-size: 8px;
    font-weight: 700;
    letter-spacing: .6px;
    text-transform: uppercase;
    backdrop-filter: blur(8px);
}

.blog-16 .blog-16-category i {
    font-size: 13px;
}

.blog-16 .blog-16-content {
    display: flex;
    flex: 1;
    flex-direction: column;
    padding: 25px 27px 28px;
}

.blog-16 .blog-16-meta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 13px;
    margin: 0 0 11px;
    color: var(--text, #222);
    opacity: .48;
    font-size: 8px;
    line-height: 1.5;
}

.blog-16 .blog-16-meta span {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

.blog-16 .blog-16-meta i {
    color: var(--primary, #0a1a44);
    font-size: 13px;
}

.blog-16 .blog-16-card-large .blog-16-card-title {
    margin: 0 0 11px;
    color: var(--text, #222);
    font-size: 22px;
    font-weight: 700;
    line-height: 1.45;
}

.blog-16 .blog-16-card-text {
    max-width: 600px;
    margin: 0;
    color: var(--text, #222);
    opacity: .52;
    font-size: 10px;
    line-height: 1.8;
}

.blog-16 .blog-16-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    width: fit-content;
    margin-top: auto;
    padding-top: 20px;
    color: var(--primary, #0a1a44);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: .7px;
    line-height: 1.5;
    text-decoration: none;
    text-transform: uppercase;
    transition: gap .3s ease, color .3s ease;
}

.blog-16 .blog-16-btn i {
    font-size: 15px;
    transition: transform .3s ease;
}

.blog-16 .blog-16-btn:hover {
    gap: 11px;
    color: var(--secondary, #243a8c);
    text-decoration: none;
}

.blog-16 .blog-16-btn:hover i {
    transform: translateX(3px);
}

.blog-16 .blog-16-small-column {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.blog-16 .blog-16-card-small {
    display: flex;
    align-items: stretch;
    min-height: 111px;
    overflow: hidden;
    border-radius: 16px;
    transition: transform .35s ease, box-shadow .35s ease, border-color .35s ease;
}

.blog-16 .blog-16-card-small:hover {
    border-color: var(--primary, #0a1a44);
    box-shadow: 0 20px 40px rgba(0, 0, 0, .1);
    transform: translateY(-4px);
}

.blog-16 .blog-16-small-image {
    flex: 0 0 145px;
    width: 145px;
    height: 111px;
    overflow: hidden;
    background: var(--secondary, #222);
}

.blog-16 .blog-16-small-image img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform .5s ease;
}

.blog-16 .blog-16-card-small:hover .blog-16-small-image img {
    transform: scale(1.05);
}

.blog-16 .blog-16-small-content {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-width: 0;
    padding: 14px 17px;
}

.blog-16 .blog-16-small-content .blog-16-meta {
    gap: 9px;
    margin-bottom: 5px;
    font-size: 7px;
}

.blog-16 .blog-16-small-content .blog-16-meta i {
    font-size: 11px;
}

.blog-16 .blog-16-card-small .blog-16-card-title {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    color: var(--text, #222);
    font-size: 12px;
    font-weight: 600;
    line-height: 1.5;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.blog-16 .blog-16-card-small .blog-16-btn {
    padding-top: 7px;
    font-size: 7px;
}

.blog-16 .blog-16-card-small .blog-16-btn i {
    font-size: 13px;
}

.blog-16 .blog-16-gototop {
    position: absolute;
    top: 50%;
    right: 22px;
    z-index: 3;
    display: flex;
    align-items: center;
    gap: 7px;
    color: var(--text, #222);
    opacity: .55;
    font-size: 8px;
    font-weight: 600;
    letter-spacing: 1px;
    text-transform: uppercase;
    transform: translateY(-50%) rotate(90deg);
}

.blog-16 .blog-16-gototop i {
    font-size: 15px;
}

.blog-16 .blog-16-gototop::before {
    content: "";
    width: 32px;
    height: 1px;
    background: var(--text, #222);
}

