    gap: 15px;
}

.testimonial-15-client img {
    width: 60px;
    height: 60px;
    border: 2px solid var(--primary, #f47c48);
    border-radius: 50%;
    object-fit: cover;
}

.testimonial-15-client h4 {
    margin: 0;
    color: var(--text, #0d2b64);
    font-size: 16px;
    font-weight: 600;
}

.testimonial-15-client span {
    color: var(--primary, #f47c48);
    font-size: 13px;
}

.testimonial-15 .carousel-indicators {
    bottom: -30px;
}

.testimonial-15 .carousel-indicators li {
    background: #ddd;
}

.testimonial-15 .carousel-indicators .active {
    background: var(--primary, #f47c48);
}

.testimonial-15-side-left,
.testimonial-15-side-right {
    position: absolute;
    top: 50%;
    display: flex;
    flex-direction: column;
    gap: 25px;
    transform: translateY(-50%);
}

.testimonial-15-side-left {
    left: 40px;
}

.testimonial-15-side-right {
    right: 40px;
}

.testimonial-15-side-left img,
.testimonial-15-side-right img {
    width: 65px;
    height: 65px;
    border-radius: 50%;
    object-fit: cover;
    box-shadow: 0 10px 25px rgba(0, 0, 0, .12);
    transition: transform .35s ease;
}

.testimonial-15-side-left img:hover,
.testimonial-15-side-right img:hover {
    transform: scale(1.1);
}

.carousel-fade .carousel-inner .item {
    opacity: 0;
    transition-property: opacity;
    transition-duration: 1s;
}

.carousel-fade .carousel-inner .active {
    opacity: 1;
}

.carousel-fade .carousel-inner .active.left,
.carousel-fade .carousel-inner .active.right {
    opacity: 0;
}

.carousel-fade .carousel-inner .next.left,
.carousel-fade .carousel-inner .prev.right {
    opacity: 1;
}

@keyframes testimonial-15-fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }

    to {
        opacity: 1;
        transform: translateY(-30px);
    }
}

.animated.fadeInUp {
    animation: testimonial-15-fadeInUp .8s ease forwards;
}

@media(max-width:991px) {

    .testimonial-15 {
        padding: 70px 0;
