    }

    .testimonial-15-desc {
        margin-bottom: 40px;
    }

}

/* services-28 */
.services-28 {
    padding: 80px 15px;
    background: var(--text, #0f1314);
    color: #e6e6e6;
}

.services-28 * {
    font-family: "Poppins", sans-serif;
}

.services-28 .container {
    max-width: 1100px;
}

.services-28 h2 {
    margin: 0 0 36px;
    color: #f6f6f6;
    font-size: 42px;
    font-weight: 700;
    line-height: 1.3;
    text-align: center;
    letter-spacing: .4px;
}

.services-28 .service-tabs {
    display: flex;
    justify-content: center;
    align-items: flex-start;
    gap: 18px;
    flex-wrap: nowrap;
    overflow-x: auto;
    margin-bottom: 28px;
    padding-bottom: 6px;
}

.services-28 .service-tab {
    position: relative;
    width: 140px;
    text-align: center;
    cursor: pointer;
    backface-visibility: hidden;
}

.services-28 .service-tab .thumb {
    display: block;
    width: 140px;
    height: 110px;
    overflow: hidden;
    border-radius: 8px;
    background: #111;
    transition: transform .35s ease, box-shadow .35s ease;
}

.services-28 .service-tab img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: grayscale(100%) contrast(.9) brightness(.85);
    transition: transform .45s ease, filter .35s ease;
}

.services-28 .service-tab:hover .thumb,
.services-28 .service-tab:focus .thumb {
    transform: translateY(-6px);
    box-shadow: 0 15px 35px rgba(0, 0, 0, .45);
}

.services-28 .service-tab.active img {
    filter: none;
    transform: scale(1.04);
}

.services-28 .service-tab .label {
    display: block;
    margin-top: 8px;
    color: #9ea0a0;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: .2px;
    transition: color .3s ease;
}

.services-28 .service-tab.active .label {
    color: #fff;
}

.services-28 .underline {
    width: 130px;
    height: 2px;
    margin: 12px auto 0;
    background: transparent;
}

.services-28 .service-tab.active .underline {
    background: var(--primary, #f0226f);
    box-shadow: 0 1px 6px rgba(240, 34, 111, .25);
}

.services-28 .divider {
    height: 1px;
    margin: 22px 0 26px;
    background: rgba(255, 255, 255, .05);
}

.services-28 .price-wrap {
    max-width: 1080px;
    margin: 0 auto;
    color: #cfcfcf;
}

.services-28 .price-list {
    display: none;
    border: 1px solid rgba(255, 255, 255, .08);
    border-radius: 20px;
    animation: services-28-fadeInUp .45s ease both;
}

.services-28 .price-list.active {
    display: block;
}

.services-28 .price-grid {
    display: flex;
    gap: 30px;
    flex-wrap: wrap;
    padding: 20px;
}

.services-28 .price-col {
    flex: 1 1 48%;
    min-width: 260px;
}

.services-28 .price-table {
    width: 100%;
}

.services-28 .price-table tr {
    border-bottom: 1px dotted rgba(255, 255, 255, .06);
}

.services-28 .price-table td {
    padding: 12px 6px;
    font-size: 14px;
    vertical-align: middle;
}

.services-28 .price-table td:first-child {
    color: #bfbfbf;
    font-weight: 600;
}

.services-28 .price-table td:last-child {
    width: 90px;
    color: var(--primary, #f0226f);
    font-weight: 700;
    text-align: right;
}

.services-28 .badge-discount {
    display: inline-block;
    margin-right: 8px;
    padding: 4px 8px;
    border-radius: 4px;
    background: var(--primary, #f0226f);
    color: #fff;
    font-size: 11px;
    font-weight: 700;
}

.services-28 .bottom-line {
    height: 1px;
    margin-top: 30px;
    background: rgba(255, 255, 255, .05);
}

.services-28 .muted {
    color: #9a9a9a;
    font-weight: 400;
}

@keyframes services-28-fadeInUp {
