.about-80 {
    padding: 80px 0;
    background: #fff;
}

.about-80 * {
    box-sizing: border-box;
    font-family: "Poppins", sans-serif;
}

.about-80-contact-wrapper {
    position: relative;
    padding: 45px;
    background: #fff;
    border-radius: 35px;
    box-shadow: 0 25px 70px rgba(0, 0, 0, .08);
    overflow: hidden;
}

.about-80-contact-wrapper:before {
    content: "";
    position: absolute;
    top: -90px;
    right: -90px;
    width: 220px;
    height: 220px;
    background: var(--primary, #15b39a);
    border-radius: 50%;
    opacity: .06;
}

.about-80-contact-wrapper:after {
    content: "";
    position: absolute;
    bottom: -70px;
    left: -70px;
    width: 180px;
    height: 180px;
    background: var(--primary, #15b39a);
    border-radius: 50%;
    opacity: .05;
}

.about-80-contact-form {
    position: relative;
    z-index: 2;
    padding: 35px;
    background: var(--light, #eaf7f4);
    border-radius: 28px;
}

.about-80-form-tag {
    display: inline-block;
    margin-bottom: 25px;
    padding: 8px 18px;
    background: var(--primary, #18a689);
    border-radius: 40px;
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 1px;
}

.about-80-form-group {
    margin-bottom: 18px;
}

.about-80-form-group label {
    display: block;
    margin-bottom: 8px;
    color: var(--text, #333333);
    font-size: 13px;
    font-weight: 600;
}

.about-80-form-group input,
.about-80-form-group select {
    width: 100%;
    height: 54px;
    padding: 0 18px;
    background: #fff;
    border: 1px solid var(--border, #d8ece8);
    border-radius: 14px;
    color: var(--text, #444444);
    outline: none;
    transition: all .35s ease;
}

.about-80-form-group input:focus,
.about-80-form-group select:focus {
    border-color: var(--primary, #18a689);
    box-shadow: 0 0 0 4px rgba(24, 166, 137, .12);
}

.about-80-submit-btn {
    width: 100%;
    height: 56px;
    background: var(--primary, #18a689);
    border: 0;
    border-radius: 30px;
    color: #fff;
    font-size: 15px;
    font-weight: 700;
    transition: all .35s ease;
}

.about-80-submit-btn:hover {
    background: var(--secondary, #13967c);
    transform: translateY(-4px);
}

.about-80-contact-content {
    position: relative;
    z-index: 2;
    padding-left: 45px;
}

.about-80-small-title {
    display: inline-block;
    margin-bottom: 18px;
    color: var(--primary, #18a689);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
}

.about-80-contact-content h2 {
    margin: 0 0 22px;
    color: var(--text, #1b1b1b);
    font-size: 48px;
    font-weight: 700;
    line-height: 1.18;
}

.about-80-contact-content p {
    margin-bottom: 30px;
    color: var(--text, #666666);
    font-size: 16px;
    line-height: 1.8;
}

.about-80-contact-image {
    overflow: hidden;
    margin-bottom: 35px;
    border-radius: 22px;
    box-shadow: 0 25px 60px rgba(0, 0, 0, .12);
}

.about-80-contact-image img {
    display: block;
    width: 100%;
    height: 260px;
    object-fit: cover;
    transition: transform .7s ease;
}

.about-80-contact-image:hover img {
    transform: scale(1.06);
}

.about-80-contact-info {
    margin-top: 10px;
}

.about-80-info-box {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    margin-bottom: 25px;
}

.about-80-info-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: 55px;
    height: 55px;
    background: var(--primary, #18a689);
    border-radius: 50%;
    color: #fff;
    font-size: 18px;
    box-shadow: 0 10px 30px rgba(24, 166, 137, .25);
}

.about-80-info-box span {
    display: block;
    margin-bottom: 5px;
    color: var(--text, #888888);
    font-size: 13px;
}

.about-80-info-box h5 {
    margin: 0;
    color: var(--text, #222222);
    font-size: 15px;
    font-weight: 600;
    line-height: 1.5;
}

@media(max-width:991px) {

    .about-80 {
        padding: 70px 0;
    }

    .about-80-contact-wrapper {
        padding: 35px;
    }

    .about-80-contact-content {
        margin-top: 50px;
        padding-left: 0;
        text-align: center;
    }

    .about-80-contact-content h2 {
        font-size: 36px;
    }

    .about-80-info-box {
        justify-content: center;
    }

}

@media(max-width:767px) {

    .about-80 {
        padding: 60px 0;
    }

    .about-80-contact-wrapper {
        padding: 25px;
        border-radius: 25px;
    }

    .about-80-contact-form {
        padding: 25px;
    }

    .about-80-contact-content h2 {
        font-size: 30px;
        line-height: 1.3;
    }

    .about-80-contact-content p {
        font-size: 15px;
        line-height: 1.8;
    }

    .about-80-contact-image img {
        height: 220px;
    }

}

